using System.Collections;
using System.Linq;
using UnityEngine;
// Owns only the entry/exit of an existing kit bath, not life or save managers.
public sealed class GridShiftHomeBath:MonoBehaviour {
 public PlayerMovement Occupant{get;private set;}public bool Entering{get;private set;}
 public enum DoorMotion {Auto,Slide,Swing}
 [Header("Porta editável") ]public DoorMotion doorMotion=DoorMotion.Auto;public Vector3 slidingOffset=new Vector3(0,0,1.3288174f);[Min(.1f)]public float doorSeconds=.5f;
 [SerializeField]bool sceneAuthored;[SerializeField]Transform glass;[SerializeField]GridShiftWorldAction use,exit;[SerializeField]Transform valve;Vector3 entryLocalPosition,glassClosedPosition;Vector3 safe;Quaternion safeRotation;CharacterController controller;bool controllerWasOn;Quaternion glassClosed;Animator glassAnimator;bool animatorWasOn;Vector3 inwardDirection;bool initialized;public bool IsTub=>name.StartsWith("BathTub");
 public Vector3 SafePosition=>safe;
 void Initialize(){if(initialized)return;initialized=true;if(glass==null)glass=GetComponentsInChildren<Transform>(true).FirstOrDefault(t=>t.name=="GlassDoor");if(glass!=null){glassClosed=glass.localRotation;glassClosedPosition=glass.localPosition;var floor=GetComponent<MeshRenderer>();var pane=glass.GetComponent<Renderer>();inwardDirection=Vector3.ProjectOnPlane((floor!=null?floor.bounds.center:transform.position)-(pane!=null?pane.bounds.center:glass.position),Vector3.up).normalized;glassAnimator=glass.GetComponent<Animator>();if(glassAnimator!=null){animatorWasOn=glassAnimator.enabled;glassAnimator.enabled=false;}}if(use==null)use=GetComponentsInChildren<GridShiftWorldAction>().FirstOrDefault(a=>a.GetComponentInParent<GridShiftHomeUse>()?.kind=="shower");if(use!=null){entryLocalPosition=use.transform.localPosition;use.title=IsTub?"Entrar na banheira":"Abrir e entrar no box";}exit=GridShiftWorldAction.Create(transform,IsTub?"Sair da banheira":"Sair do box",transform.InverseTransformPoint(glass!=null?glass.position:transform.position),p=>{if(Occupant!=p||Entering||GridShiftLife.Instance.Acting)return false;StartCoroutine(Leave());return true;});GridShiftApartment.NormalizeFocus(exit.transform);exit.focusOwner=glass;exit.sightRoot=transform;exit.focusOffset=Vector3.zero;exit.range=3;exit.available=()=>Occupant!=null&&!Entering&&!GridShiftLife.Instance.Acting;}
 void Start(){Initialize();}
 public bool Use(PlayerMovement player){Initialize();if(Entering||GridShiftLife.Instance.Acting)return false;if(Occupant==player)return GridShiftLife.Instance.Use("shower",player,transform);if(Occupant!=null)return false;StartCoroutine(Enter(player));return true;}
 public void AuthorScene(){Initialize();EnsureValve();sceneAuthored=true;if(use!=null)use.sceneAuthored=true;if(exit!=null)exit.sceneAuthored=true;}
 IEnumerator Door(bool open){if(glass==null)yield break;bool slide=doorMotion==DoorMotion.Slide||(doorMotion==DoorMotion.Auto&&IsTub);var from=glass.localRotation;var fromAt=glass.localPosition;var to=glassClosed*Quaternion.Euler(0,open&&!slide?85:0,0);var at=glassClosedPosition+(open&&slide?slidingOffset:Vector3.zero);for(float t=0;t<doorSeconds;t+=Time.deltaTime){float k=Mathf.SmoothStep(0,1,t/doorSeconds);glass.localRotation=Quaternion.Slerp(from,to,k);glass.localPosition=Vector3.Lerp(fromAt,at,k);yield return null;}glass.localRotation=to;glass.localPosition=at;}
 void EnsureValve(){if(valve!=null)return;var body=GetComponent<MeshRenderer>();var b=body!=null?body.bounds:new Bounds(transform.position,Vector3.one);var destination=new Vector3(b.center.x,IsTub?b.min.y+.33f:b.max.y+.03f,b.center.z);var inward=inwardDirection.sqrMagnitude>.01f?inwardDirection:Vector3.forward;if(valve==null){var knob=GameObject.CreatePrimitive(PrimitiveType.Cylinder);knob.name="Bath water control";knob.transform.SetParent(transform,false);knob.GetComponent<Collider>().enabled=false;knob.GetComponent<Renderer>().sharedMaterial=Resources.Load<GridShiftActiveConfig>("GridShiftActiveConfig").structureMaterial;valve=knob.transform;valve.localScale=Vector3.one;}float span=Mathf.Min(Mathf.Abs(inward.x)>.01f?b.extents.x/Mathf.Abs(inward.x):100,Mathf.Abs(inward.z)>.01f?b.extents.z/Mathf.Abs(inward.z):100);valve.position=destination+inward*Mathf.Max(.2f,span-.045f)+Vector3.up*1.3f;valve.rotation=Quaternion.FromToRotation(Vector3.up,-inward);valve.localScale=Vector3.one;var scale=valve.lossyScale;valve.localScale=new Vector3(.08f/Mathf.Abs(scale.x),.012f/Mathf.Abs(scale.y),.08f/Mathf.Abs(scale.z));}

 IEnumerator Enter(PlayerMovement p){Entering=true;Occupant=p;safe=p.transform.position;safeRotation=p.transform.rotation;controller=p.GetComponent<CharacterController>();controllerWasOn=controller.enabled;p.BlockControls(true);yield return Door(true);controller.enabled=false;var body=GetComponent<MeshRenderer>();var b=body!=null?body.bounds:new Bounds(transform.position,Vector3.one);var destination=new Vector3(b.center.x,IsTub?b.min.y+.33f:b.max.y+.03f,b.center.z);var from=p.transform.position;for(float t=0;t<.65f;t+=Time.deltaTime){p.transform.position=Vector3.Lerp(from,destination,Mathf.SmoothStep(0,1,t/.65f))+Vector3.up*Mathf.Sin(t/.65f*Mathf.PI)*.15f;yield return null;}p.transform.position=destination;var inward=inwardDirection.sqrMagnitude>.01f?inwardDirection:Vector3.forward;if(inward.sqrMagnitude>.01f)p.transform.rotation=Quaternion.LookRotation(inward);p.CameraTransform.localRotation=Quaternion.identity;Physics.SyncTransforms();yield return Door(false);if(use!=null){EnsureValve();use.focusOwner=valve;use.title="Tomar banho";use.transform.position=valve.position;use.focusOffset=Vector3.zero;use.focusSize=new Vector3(.4f,.4f,.4f);if(use.FocusCollider is BoxCollider box){box.center=Vector3.zero;box.size=use.focusSize;}use.available=()=>Occupant==p&&!Entering&&!GridShiftLife.Instance.Acting;}p.BlockControls(false);Entering=false;}
 IEnumerator Leave(){Entering=true;var p=Occupant;p.BlockControls(true);yield return Door(true);var from=p.transform.position;for(float t=0;t<.55f;t+=Time.deltaTime){p.transform.position=Vector3.Lerp(from,safe,Mathf.SmoothStep(0,1,t/.55f));yield return null;}Restore();yield return Door(false);Entering=false;}
 void Restore(){if(Occupant!=null){Occupant.transform.SetPositionAndRotation(safe,safeRotation);if(controller!=null)controller.enabled=controllerWasOn;Occupant.BlockControls(false);}Occupant=null;if(use!=null){use.title=IsTub?"Entrar na banheira":"Abrir e entrar no box";var marker=GetComponent<GridShiftHomeUse>();use.transform.localPosition=sceneAuthored?entryLocalPosition:marker.localPoint;use.available=null;use.focusOwner=transform;}Physics.SyncTransforms();}
 public static Vector3 SavePosition(PlayerMovement player){foreach(var bath in Object.FindObjectsByType<GridShiftHomeBath>(FindObjectsSortMode.None))if(bath.Occupant==player)return bath.safe;return player!=null?player.transform.position:Vector3.zero;}
 void OnDisable(){if(Occupant!=null)Restore();if(glass!=null){glass.localRotation=glassClosed;glass.localPosition=glassClosedPosition;}if(glassAnimator!=null)glassAnimator.enabled=animatorWasOn;}
}
